(()=>{
'use strict';
const $=id=>document.getElementById(id),defs=window.RainSeasons.definitions;
const num=n=>n===null?'—':n.toLocaleString('nb-NO',{maximumFractionDigits:1}),signed=n=>(n>=0?'+':'−')+num(Math.abs(n))+' %';
const month=k=>new Intl.DateTimeFormat('nb-NO',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(k+'-15T12:00:00Z'));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let model,expanded=false;
function rebuild(){model=window.RainSeasons.create(window.RAIN_DATA,today());const old=$('seasonYear').value;$('seasonYear').innerHTML=Array.from({length:model.last-model.first+1},(_,i)=>`<option>${model.last-i}</option>`).join('');$('seasonYear').value=old||String(model.last);renderRecords();render()}
function renderRecords(){const r=model.records();$('seasonRecords').innerHTML=`<article class="panel season-record"><p class="eyebrow">Våteste måned</p><strong>${num(r.month[0]?.mm??null)} mm</strong><p>${r.month.map(r=>month(r.month)).join(' · ')}</p><span class="small muted">Alle kalendermåneder</span></article>`+Object.entries(defs).map(([type,d])=>{const matches=r.seasons[type];return `<article class="panel season-record"><p class="eyebrow">Våteste ${d.name.toLowerCase()}</p><strong>${num(matches[0]?.actual??null)} mm</strong><p>${matches.map(r=>`<button class="text-button" data-season="${type}" data-year="${r.year}">${d.name} ${r.label} ↗</button>`).join(' · ')}</p><span class="small muted">${d.months.map(m=>month('2000-'+String(m).padStart(2,'0')).split(' ')[0].slice(0,3)).join(' · ')}</span></article>`}).join('');$('seasonRecords').querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{select(+b.dataset.year,b.dataset.season);$('seasonLookup').scrollIntoView({behavior:'smooth',block:'start'})})}
function select(year,type){$('seasonYear').value=year;$('seasonType').value=type;render()}
function render(){const y=+$('seasonYear').value,type=$('seasonType').value,r=model.season(y,type),ranked=model.ranked(type),rank=r.complete&&!r.provisional?1+ranked.filter(x=>x.actual>r.actual+1e-8).length:null;
 $('seasonPrevious').disabled=y<=model.first;$('seasonNext').disabled=y>=model.last;
 $('seasonTitle').textContent=defs[type].name+' '+r.label;
 $('seasonSummary').innerHTML=`<div><span>${r.complete?'Samlet nedbør':'Målt i tilgjengelige måneder'}</span><strong>${num(r.actual)}${r.actual===null?'':' mm'}</strong><small>${r.complete?'Hele årstiden':r.count+' av 3 hele måneder tilgjengelig'}</small></div><div><span>Normal 1991–2020</span><strong>${num(r.normal)} mm</strong><small>Hele årstiden</small></div><div><span>Avvik fra normalen</span><strong>${r.percent===null?'—':signed(r.percent)}</strong><small>${r.complete?'Samme tre måneder':'Beregnes når alle tre måneder er komplette'}</small></div><div><span>Plass blant de våteste</span><strong>${rank===null?'—':rank+' / '+ranked.length}</strong><small>${r.provisional?'Foreløpige data · utenfor rangeringen':rank===null?'Ufullstendige årstider rangeres ikke':'1 er våtest · fra '+Math.max(1896,model.first)+' · lik sum gir delt plass'}</small></div>`;
 $('seasonMonths').innerHTML=r.months.map(m=>`<tr><th scope="row">${month(m.month)}</th><td>${num(m.mm)}${m.mm===null?'':' mm'}</td><td>${num(m.normal)} mm</td><td>${m.mm===null||!m.normal?'—':signed(100*(m.mm/m.normal-1))}</td></tr>`).join('');
 const max=Math.max(1,...r.months.flatMap(m=>[m.mm??0,m.normal??0]));$('seasonBars').innerHTML=r.months.map(m=>`<div class="season-bar-row"><span>${month(m.month)}</span><div><div class="season-bar measured" style="width:${100*(m.mm??0)/max}%"></div><div class="season-bar normal" style="width:${100*(m.normal??0)/max}%"></div></div><strong>${num(m.mm)}${m.mm===null?'':' mm'}</strong></div>`).join('');
 $('seasonTableTitle').textContent='Sammenlign '+defs[type].name.toLowerCase()+' fra år til år';let list=model.all(type);if(!expanded)list=list.slice(0,30);$('seasonRows').innerHTML=list.map(a=>`<tr${a.year===y?' class="selected-month"':''}><td><button data-year="${a.year}">${a.label}</button></td><td>${num(a.actual)}${a.actual===null?'':' mm'}</td><td>${a.percent===null?'—':signed(a.percent)}</td><td>${a.provisional?'Foreløpig · ':''}${a.complete?'Komplett':a.count+'/3 hele måneder'}</td></tr>`).join('');$('seasonRows').querySelectorAll('button').forEach(b=>b.onclick=()=>{select(+b.dataset.year,type);$('seasonLookup').scrollIntoView({behavior:'smooth'})});$('seasonAll').textContent=expanded?'Vis de 30 nyeste årene':'Vis alle år';
}
$('seasonType').onchange=render;$('seasonYear').onchange=render;$('seasonPrevious').onclick=()=>select(+$('seasonYear').value-1,$('seasonType').value);$('seasonNext').onclick=()=>select(+$('seasonYear').value+1,$('seasonType').value);$('seasonAll').onclick=()=>{expanded=!expanded;render()};window.addEventListener('frost-updated',rebuild);window.addEventListener('pageshow',rebuild);rebuild();
})();
